require_once "config/database.php";require_once "includes/functions.php";require_login();$s=$pdo->prepare("SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC");$s->execute([$_SESSION['user']['id']]);$orders=$s->fetchAll();$page_title="My Orders";include "includes/header.php";?><div class="container py-5"><h2>My Orders</h2><div class="table-responsive mt-3"><table class="table bg-white"><thead><tr><th>Order</th><th>Total</th><th>Payment</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><?=e($o['order_number'])?><br><small><?=e($o['created_at'])?></small></td><td><?=money($o['total_amount'])?></td><td><?=e($o['payment_method'])?></td><td><span class="badge text-bg-danger"><?=e($o['order_status'])?></span></td><td><a class="btn btn-sm btn-outline-danger" href="track-order.php?id=<?=$o['id']?>">Track</a></td></tr><?php endforeach;?></tbody></table></div></div><?php include "includes/footer.php"; ?>